const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0];
const f = [0, ...tok.slice(1, 1 + n)];
const pre = new Array(n + 1).fill(0);
for (let i = 1; i <= n; i++) pre[i] = pre[i - 1] + f[i];
const dp = Array.from({ length: n + 2 }, () => new Array(n + 2).fill(0));
const opt = Array.from({ length: n + 2 }, () => new Array(n + 2).fill(0));
for (let i = 1; i <= n; i++) { dp[i][i] = f[i]; opt[i][i] = i; }
for (let len = 2; len <= n; len++) {
  for (let i = 1; i + len - 1 <= n; i++) {
    const j = i + len - 1;
    let best = Infinity, bk = i;
    for (let r = opt[i][j - 1]; r <= opt[i + 1][j]; r++) {
      const v = dp[i][r - 1] + dp[r + 1][j];
      if (v < best) { best = v; bk = r; }
    }
    dp[i][j] = best + pre[j] - pre[i - 1];
    opt[i][j] = bk;
  }
}
