import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        long[] pre = new long[n + 1];
        long[] f = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            in.nextToken();
            f[i] = (long) in.nval;
            pre[i] = pre[i - 1] + f[i];
        }
        long[][] dp = new long[n + 2][n + 2];
        int[][] opt = new int[n + 2][n + 2];
        for (int i = 1; i <= n; i++) { dp[i][i] = f[i]; opt[i][i] = i; }
        for (int len = 2; len <= n; len++) {
            for (int i = 1; i + len - 1 <= n; i++) {
                int j = i + len - 1;
                long best = Long.MAX_VALUE;
                int bk = i;
                for (int r = opt[i][j - 1]; r <= opt[i + 1][j]; r++) {
                    long v = dp[i][r - 1] + dp[r + 1][j];
                    if (v < best) { best = v; bk = r; }
                }
                dp[i][j] = best + pre[j] - pre[i - 1];
                opt[i][j] = bk;
            }
        }
        System.out.println(dp[1][n]);
    }
}

