#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    int n;
    scanf("%d", &n);
    vector<ll> f(n + 1, 0), pre(n + 1, 0);
    for (int i = 1; i <= n; i++) {
        scanf("%lld", &f[i]);
        pre[i] = pre[i - 1] + f[i];
    }
    vector<vector<ll>> dp(n + 2, vector<ll>(n + 2, 0));
    vector<vector<int>> opt(n + 2, vector<int>(n + 2, 0));
    for (int i = 1; i <= n; i++) { dp[i][i] = f[i]; opt[i][i] = i; }
    for (int len = 2; len <= n; len++) {
        for (int i = 1; i + len - 1 <= n; i++) {
            int j = i + len - 1;
            ll best = LLONG_MAX;
            int bk = i;
            for (int r = opt[i][j - 1]; r <= opt[i + 1][j]; r++) {
                ll v = dp[i][r - 1] + dp[r + 1][j];
                if (v < best) { best = v; bk = r; }
            }
            dp[i][j] = best + pre[j] - pre[i - 1];
            opt[i][j] = bk;
        }
    }
    printf("%lld\n", dp[1][n]);
    return 0;
}
